css='''@font-face{font-family:DM;src:url(assets/DMSans.ttf)}*{box-sizing:border-box}body{margin:0;background:#101827;color:#EDEAE4;font-family:DM,sans-serif}#root{position:relative;width:1080px;height:1920px;overflow:hidden}.scene{position:absolute;inset:0;background:radial-gradient(ellipse at 48% 40%,#1b293c,#101827 70%);opacity:0}.scene:first-child{opacity:1}.scene-content{width:100%;height:100%;padding:260px 120px 420px 80px;display:flex;flex-direction:column;gap:30px}.label{font-size:56px;font-weight:500;letter-spacing:-1.6px;margin:0}.graphic{position:absolute;top:425px;left:80px;width:850px;height:850px}.graphic svg{width:100%;height:100%;overflow:visible}.portrait .graphic{top:350px;left:105px;width:780px;height:490px}.talent{position:absolute;left:215px;top:790px;width:650px;height:550px;object-fit:contain;object-position:center bottom}.caption{position:absolute;left:80px;top:1370px;width:880px;height:275px;text-align:left;display:flex;flex-direction:column;gap:18px;padding-left:24px;border-left:3px solid #C5B69A}.en{font-size:53px;font-weight:600;line-height:1.14;letter-spacing:-.8px}.id{font-size:39px;font-weight:400;line-height:1.2;color:#C5B69A}.brand{position:absolute;left:80px;top:1710px;font-size:30px;letter-spacing:5px;color:#718A83}'''
sections=[];js=[]
for key,s,e,label,layout,action in beats:
    image=f'<img class="talent" src="assets/talent-{3 if key=="grow" else 39}.png" alt="Talent mask pilot">' if layout=='portrait' else ''
    sections.append(f'<section class="scene {layout}" id="scene-{key}"><div class="scene-content"><h1 class="label">{E(label)}</h1></div><div class="graphic"><svg viewBox="0 0 800 800" xmlns="http://www.w3.org/2000/svg">{art[key]}</svg></div>{image}</section>')
    js += [f'tl.set("#scene-{key}",{{opacity:1}},{s});',f'tl.set("#scene-{key}",{{opacity:0}},{e});']
for i,c in enumerate(captions):
    sections.append(f'<div class="clip caption" id="caption-{i}" data-start="{c["start"]}" data-duration="{c["end"]-c["start"]}" data-track-index="5"><span class="en">{E(c["en"])}</span><span class="id">{E(c["id"])}</span></div>')
js+=['tl.to("#g-dot1",{x:420,y:-80,duration:4.4,ease:"sine.inOut"},.5);','tl.to("#g-dot2",{x:100,y:130,duration:3,ease:"sine.inOut"},2.8);','tl.to("#page",{scaleX:-.95,svgOrigin:"400 175",duration:1.7,ease:"sine.inOut"},8);','tl.to("#d-dot1",{keyframes:[{attr:{cx:345,cy:318}},{attr:{cx:255,cy:260}},{attr:{cx:175,cy:150}}],duration:3.4,ease:"sine.inOut"},15);','tl.to("#d-dot2",{keyframes:[{attr:{cx:400,cy:390}},{attr:{cx:455,cy:318}},{attr:{cx:545,cy:260}},{attr:{cx:625,cy:150}}],duration:3.7,ease:"sine.inOut"},17);','tl.to("#door",{scaleX:.23,svgOrigin:"300 135",duration:1.6,ease:"sine.inOut"},22.4);','tl.to("#threshold-dot",{x:285,duration:3.8,ease:"sine.inOut"},24);','tl.from("#leaf1",{scale:0,svgOrigin:"665 545",duration:1.4,ease:"sine.out"},26);','tl.from("#leaf2",{scale:0,svgOrigin:"673 495",duration:1.4,ease:"sine.out"},27);','tl.to("#past-dot",{x:265,y:-150,duration:2.5,ease:"sine.inOut"},31.8);','tl.to("#new-orbit",{scale:1.16,svgOrigin:"400 300",duration:5,ease:"sine.inOut"},35);','tl.from("#final-leaf",{scaleY:.3,svgOrigin:"400 410",duration:2.5,ease:"sine.out"},36);']
doc='<!doctype html><html lang="en"><head><meta charset="utf-8"><script src="assets/gsap.min.js"></script><style>'+css+'</style></head><body><div id="root" data-composition-id="growing-means" data-start="0" data-duration="43.433" data-width="1080" data-height="1920">'+''.join(sections)+'<div class="brand">NAZARVERSE</div><audio id="voice" class="clip" src="assets/voice.wav" data-start="0" data-duration="43.433" data-track-index="9"></audio></div><script>const tl=gsap.timeline({paused:true});'+''.join(js)+'window.__timelines={"growing-means":tl};</script></body></html>'
(H/'index.html').write_text(doc,encoding='utf-8');(P/'beat-sheet.json').write_text(json.dumps([dict(id=k,start=s,end=e,label=l,layout=lo,action=a) for k,s,e,l,lo,a in beats],indent=2),encoding='utf-8')
print('6 scenes / 17 bilingual captions / storyboard-only mask pilots')
